const input=$('Execute Workflow Trigger').first().json;
const text=$input.first().json.choices?.[0]?.message?.content;
if(typeof text!=='string')throw new Error('Groq structured extraction response has no content');
let parsed;try{parsed=JSON.parse(text)}catch(e){throw new Error('Groq structured extraction returned invalid JSON')}
return [{json:{...input,triage:parsed}}];
